import{_ as d,o as t,c as o,a6 as a}from"./chunks/framework.BrkgobfX.js";const E=JSON.parse('{"title":"环境变量","description":"Codex CLI 读取的环境变量，以及它注入给子进程的环境变量","frontmatter":{"title":"环境变量","description":"Codex CLI 读取的环境变量，以及它注入给子进程的环境变量","source":"https://daiw.org/manual/codex/environment-variables"},"headers":[],"relativePath":"manual/agent/codex/environment-variables.md","filePath":"manual/agent/codex/environment-variables.md"}'),s={name:"manual/agent/codex/environment-variables.md"};function i(c,e,n,l,r,h){return t(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h1><blockquote><p>Codex CLI 读取的环境变量，以及它注入给子进程的环境变量</p></blockquote><p>Codex 的持久设置写在 <code>config.toml</code> 里；环境变量适合按 shell 临时覆盖、传入自动化所需的密钥、控制安装脚本和诊断输出。下表以官方 Environment variables 文档为主，标注“源码”的条目是在 v0.167.0 仓库中确认、但官方文档未列出的补充项，可能随版本变化。</p><p>自定义模型提供方所用的 API key 变量名由 <code>model_providers.&lt;id&gt;.env_key</code> 自行指定（如 <code>MISTRAL_API_KEY</code>），不是固定的 Codex 变量，这里不列出，见<a href="/Front2Full/manual/agent/codex/configuration">配置文件 config.toml</a>。</p><h2 id="路径与状态" tabindex="-1">路径与状态 <a class="header-anchor" href="#路径与状态" aria-label="Permalink to &quot;路径与状态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>CODEX_HOME</code></td><td><code>~/.codex</code></td><td>Codex 状态的根目录，配置、认证、日志、会话、技能以及独立安装包的元数据都在这里；CLI、IDE 扩展、app-server 与安装脚本都会读取。<strong>设置时该目录必须已存在</strong>，否则启动报错</td></tr><tr><td><code>CODEX_SQLITE_HOME</code></td><td>同 <code>CODEX_HOME</code></td><td>SQLite 状态库的存放目录；配置项 <code>sqlite_home</code> 优先于它，相对路径按当前工作目录解析</td></tr></tbody></table><p>用不同的 <code>CODEX_HOME</code> 可以让多套配置和账号并存：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.codex-work&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">alias</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> codex-work</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CODEX_HOME=&quot;$HOME/.codex-work&quot; codex&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex-work</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Codex 启动时还会读取 <code>$CODEX_HOME/.env</code>（默认 <code>~/.codex/.env</code>；源码行为，官方文档未提及），把其中的变量写入自身的进程环境，与 shell 里已有的变量同名时以文件为准；名称以 <code>CODEX_</code> 开头的变量（不分大小写）一律忽略，所以 <code>CODEX_HOME</code>、<code>CODEX_API_KEY</code> 这类变量写在这里不会生效。这些变量和其他环境变量一样，会按 <code>shell_environment_policy</code> 传给模型运行的命令。</p><h2 id="安装脚本" tabindex="-1">安装脚本 <a class="header-anchor" href="#安装脚本" aria-label="Permalink to &quot;安装脚本&quot;">​</a></h2><p>以下变量作用于 <code>https://chatgpt.com/codex/install.sh</code> 与 <code>install.ps1</code> 两个安装脚本：</p><table tabindex="0"><thead><tr><th>变量</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>CODEX_NON_INTERACTIVE</code></td><td><code>false</code></td><td>设为 <code>1</code>、<code>true</code> 或 <code>yes</code> 时跳过安装提示、采用默认答案，用于脚本化安装与更新</td></tr><tr><td><code>CODEX_INSTALL_DIR</code></td><td>macOS / Linux 为 <code>~/.local/bin</code>，Windows 为 <code>%LOCALAPPDATA%\\Programs\\OpenAI\\Codex\\bin</code></td><td><code>codex</code> 命令的安装目录；安装包缓存仍在 <code>CODEX_HOME/packages/standalone</code></td></tr><tr><td><code>CODEX_RELEASE</code>（源码）</td><td><code>latest</code></td><td>要安装的版本号，如 <code>0.167.0</code>；v0.155.0 起，指定版本安装后后台守护进程不再自动更新</td></tr><tr><td><code>CODEX_INSTALLER_USE_RELEASES_OPENAI_COM</code>（源码）</td><td><code>true</code></td><td>设为 <code>false</code>、<code>0</code> 或 <code>no</code> 时只从 GitHub Releases 下载</td></tr></tbody></table><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://chatgpt.com/codex/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CODEX_NON_INTERACTIVE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CODEX_NON_INTERACTIVE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">chatgpt.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">codex</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="认证" tabindex="-1">认证 <a class="header-anchor" href="#认证" aria-label="Permalink to &quot;认证&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>适用范围</th><th>说明</th></tr></thead><tbody><tr><td><code>CODEX_API_KEY</code></td><td><code>codex exec</code>、<code>codex review</code>、TypeScript SDK、<code>codex exec-server --remote</code></td><td>给非交互进程提供 API key。在会运行仓库代码的 CI 中，只对 Codex 这一条命令设置，不要设成整个 job 的环境变量</td></tr><tr><td><code>CODEX_ACCESS_TOKEN</code></td><td>CLI、app-server、受信任的自动化</td><td>提供 ChatGPT / Codex access token；需要持久登录时用 <code>printenv CODEX_ACCESS_TOKEN | codex login --with-access-token</code></td></tr><tr><td><code>OPENAI_API_KEY</code>（源码）</td><td>交互式登录界面</td><td>选择 API key 登录时用它预填输入框。内置的 <code>openai</code> 提供方不会直接读取它，需要先 <code>codex login --with-api-key</code>，或在自定义提供方中用 <code>env_key</code> 引用</td></tr><tr><td><code>OPENAI_ORGANIZATION</code> / <code>OPENAI_PROJECT</code>（源码）</td><td>内置 <code>openai</code> 提供方</td><td>设置后分别作为 <code>OpenAI-Organization</code>、<code>OpenAI-Project</code> 请求头发送</td></tr><tr><td><code>OPENAI_FEDERATION_RULE_ID</code></td><td>workload identity</td><td>选择该工作负载所用的联合规则</td></tr><tr><td><code>OPENAI_IDENTITY_TOKEN_FILE</code></td><td>workload identity</td><td>保存当前 OIDC token 或 SPIFFE JWT-SVID 的文件的绝对路径</td></tr><tr><td><code>OPENAI_WORKLOAD_IDENTITY_CONTEXT</code></td><td>workload identity</td><td>可选，提供用于审计归属的有界 JSON 标识，不影响认证与授权</td></tr></tbody></table><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 只为这一次运行提供 API key</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CODEX_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$MY_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;triage open bug reports&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>使用内置的云平台提供方时，认证走各平台的标准环境变量：</p><ul><li><strong>Amazon Bedrock</strong>（<code>model_provider = &quot;amazon-bedrock&quot;</code>）：可用 <code>AWS_BEARER_TOKEN_BEDROCK</code>（Bedrock API key）、<code>AWS_ACCESS_KEY_ID</code> / <code>AWS_SECRET_ACCESS_KEY</code> / <code>AWS_SESSION_TOKEN</code> 或 <code>AWS_PROFILE</code>，并用 <code>AWS_REGION</code> 指定区域。</li><li><strong>Google Cloud Vertex AI</strong>（<code>model_provider = &quot;gcp&quot;</code>，v0.165.0 起）：可用 <code>GOOGLE_CLOUD_PROJECT</code>（项目 ID）、<code>GOOGLE_CLOUD_LOCATION</code>（区域，默认 <code>global</code>）与 <code>GOOGLE_APPLICATION_CREDENTIALS</code>（ADC 凭据 JSON 文件路径）。</li></ul><h2 id="网络与证书" tabindex="-1">网络与证书 <a class="header-anchor" href="#网络与证书" aria-label="Permalink to &quot;网络与证书&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>CODEX_CA_CERTIFICATE</code></td><td>指向 PEM 格式的 CA 证书包，用于公司 TLS 拦截代理或私有根证书；登录、普通 HTTPS 请求与安全 WebSocket 连接都使用它，优先于 <code>SSL_CERT_FILE</code></td></tr><tr><td><code>SSL_CERT_FILE</code></td><td>未设置 <code>CODEX_CA_CERTIFICATE</code> 时使用的 CA 证书包</td></tr><tr><td><code>HTTPS_PROXY</code> / <code>HTTP_PROXY</code> / <code>ALL_PROXY</code> / <code>NO_PROXY</code>（源码）</td><td>Codex 自身的出站请求默认沿用 HTTP 客户端库 reqwest 的代理行为，会读取这些标准代理变量；<code>codex doctor</code> 会报告它们的设置情况。v0.156.0 起，登录与启动阶段的账户发现、云端配置等请求直连失败时，还会改走操作系统设置的代理重试（功能开关 <code>system_proxy_fallback</code>，默认开启）；v0.167.0 起另提供实验开关 <code>respect_system_proxy</code></td></tr></tbody></table><h2 id="本地模型-实验性" tabindex="-1">本地模型（实验性） <a class="header-anchor" href="#本地模型-实验性" aria-label="Permalink to &quot;本地模型（实验性）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>CODEX_OSS_BASE_URL</code>（源码）</td><td><code>--oss</code> 模式下本地提供方的完整 base URL，默认 <code>http://localhost:&lt;端口&gt;/v1</code></td></tr><tr><td><code>CODEX_OSS_PORT</code>（源码）</td><td>只改端口，默认 Ollama 为 <code>11434</code>、LM Studio 为 <code>1234</code></td></tr></tbody></table><p>源码注释说明这两个变量属于实验性质，将来可能改为从 <code>config.toml</code> 读取。</p><h2 id="执行环境-实验性" tabindex="-1">执行环境（实验性） <a class="header-anchor" href="#执行环境-实验性" aria-label="Permalink to &quot;执行环境（实验性）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>CODEX_EXEC_SERVER_URL</code>（源码）</td><td>让模型的命令与文件操作在指定的 exec-server 上执行（如 <code>ws://127.0.0.1:4501</code>，服务端用 <code>codex exec-server</code> 启动）；设为 <code>none</code> 时不提供 shell 与文件系统工具。设置了它的交互式启动不会连接或自动启动共享的后台服务，以免丢掉这里指定的执行环境</td></tr></tbody></table><h2 id="日志与诊断" tabindex="-1">日志与诊断 <a class="header-anchor" href="#日志与诊断" aria-label="Permalink to &quot;日志与诊断&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>RUST_LOG</code></td><td>CLI 与 app-server 的日志过滤，如 <code>error</code>、<code>warn</code>、<code>info</code>、<code>debug</code>、<code>trace</code>，也可以写 <code>codex_core=debug,codex_tui=debug</code> 这样的定向过滤；<code>codex exec</code> 默认为 <code>error</code></td></tr><tr><td><code>CODEX_TUI_RECORD_SESSION</code>（源码）</td><td>设为 <code>1</code>、<code>true</code> 或 <code>yes</code> 时把 TUI 会话事件记录为 JSONL，默认写到日志目录下的 <code>session-&lt;时间戳&gt;.jsonl</code></td></tr><tr><td><code>CODEX_TUI_SESSION_LOG_PATH</code>（源码）</td><td>配合上一项，指定记录文件的路径</td></tr><tr><td><code>CODEX_TUI_DISABLE_KEYBOARD_ENHANCEMENT</code>（源码）</td><td>设为 <code>1</code>、<code>true</code> 或 <code>yes</code> 关闭终端的键盘增强协议，设为 <code>0</code>、<code>false</code> 或 <code>no</code> 强制开启；未设置时，只在 WSL 中判断为（或无法排除是）VS Code 终端时自动关闭</td></tr></tbody></table><p>交互模式默认把诊断信息记录在有容量上限的本地存储中，纯文本日志 <code>codex-tui.log</code> 需要显式设置 <code>log_dir</code>（默认 <code>$CODEX_HOME/log</code>）才会生成：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RUST_LOG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">debug</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> codex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log_dir=./.codex-log</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./.codex-log/codex-tui.log</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>codex exec</code> 把日志直接打印在输出中，不单独写 TUI 日志文件。</p><h2 id="编辑器" tabindex="-1">编辑器 <a class="header-anchor" href="#编辑器" aria-label="Permalink to &quot;编辑器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>VISUAL</code> / <code>EDITOR</code></td><td>在输入框中按 <code>Ctrl+G</code> 时打开的外部编辑器，优先使用 <code>VISUAL</code>，未设置时用 <code>EDITOR</code>；保存并关闭编辑器后，文本回到输入框</td></tr></tbody></table><h2 id="codex-注入给子进程的变量" tabindex="-1">Codex 注入给子进程的变量 <a class="header-anchor" href="#codex-注入给子进程的变量" aria-label="Permalink to &quot;Codex 注入给子进程的变量&quot;">​</a></h2><p>Codex 为模型生成的命令创建子进程时，会在环境中加入以下变量（均来自源码），脚本可以据此判断自己是否运行在 Codex 里。你自己的哪些环境变量会被传给子进程，由配置项 <code>shell_environment_policy</code> 决定。</p><table tabindex="0"><thead><tr><th>变量</th><th>取值与含义</th></tr></thead><tbody><tr><td><code>CODEX_THREAD_ID</code></td><td>当前线程（会话）的 ID</td></tr><tr><td><code>CODEX_SESSION_ID</code> / <code>CODEX_VERSION</code></td><td>根会话 ID 与 Codex 版本号</td></tr><tr><td><code>CODEX_SANDBOX</code></td><td>命令运行在 macOS Seatbelt 沙箱内时为 <code>seatbelt</code></td></tr><tr><td><code>CODEX_SANDBOX_NETWORK_DISABLED</code></td><td>该命令的网络访问受沙箱限制时为 <code>1</code></td></tr><tr><td><code>CODEX_PERMISSION_PROFILE</code></td><td>当前命名权限配置的名称，仅供参考；子进程可以改写它，不能当作权限已被强制执行的证明</td></tr><tr><td><code>CODEX_CI=1</code> 等</td><td>经 unified exec（默认开启）运行的命令还会被设置 <code>NO_COLOR=1</code>、<code>TERM=dumb</code>、<code>PAGER=cat</code>、<code>GIT_PAGER=cat</code>、<code>GH_PAGER=cat</code>，清空 <code>COLORTERM</code>，并把 <code>LANG</code>、<code>LC_CTYPE</code>、<code>LC_ALL</code> 设为 <code>C.UTF-8</code></td></tr></tbody></table>`,36)])])}const k=d(s,[["render",i]]);export{E as __pageData,k as default};
